import { sql } from "drizzle-orm";
import { date, index, integer, jsonb, primaryKey, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import type { AssistantMessageMeta } from "../../types/asistente";
import type { AppliedChange, DeferredItem, ProposalChange } from "../../types/calendario";
import type { AssistantContext } from "../../types/redesign";
import { assistantActionStatus, assistantRole, core, proposalKind, proposalStatus, soft, stamps } from "./_schema";
import { staff } from "./people";

/** Server-side assistant threads (BE §3.10). The id is generated by the client (review B9). */
export const assistantThreads = core.table(
  "assistant_threads",
  {
    id: uuid("id").primaryKey(),
    staffId: uuid("staff_id")
      .notNull()
      .references(() => staff.id, { onDelete: "cascade" }),
    title: text("title").notNull().default("Nueva conversación"),
    context: jsonb("context").$type<AssistantContext>(),
    /** "localStorage" for `importLegacyAssistantThreadAction`. */
    importedFrom: text("imported_from"),
    /** Pinned in the Visual threads rail ("Fijadas"); null = not pinned. */
    pinnedAt: timestamp("pinned_at", { withTimezone: true }),
    /** When the owner last read the thread: an assistant message after it is "Nueva respuesta". */
    lastReadAt: timestamp("last_read_at", { withTimezone: true }),
    /** Non-widget tool calls in the thread's assistant messages, kept by `saveThreadMessages` (Asistente Analítico rail). */
    toolCallCount: integer("tool_call_count").notNull().default(0),
    ...stamps,
    ...soft,
  },
  (t) => [
    index("idx_assistant_threads_staff").on(t.staffId, t.updatedAt).where(sql`${t.deletedAt} is null`),
    index("idx_assistant_threads_staff_pinned").on(t.staffId, t.pinnedAt.desc().nullsLast(), t.updatedAt.desc()),
  ]
);

/** AI SDK UIMessages per thread; the id is unique per thread only (review R2-4). */
export const assistantMessages = core.table(
  "assistant_messages",
  {
    id: text("id").notNull(),
    threadId: uuid("thread_id")
      .notNull()
      .references(() => assistantThreads.id, { onDelete: "cascade" }),
    role: assistantRole("role").notNull(),
    parts: jsonb("parts").$type<unknown[]>().notNull(),
    /** Tool durations, response time and token usage; null on rows written before it existed. */
    metadata: jsonb("metadata").$type<Omit<AssistantMessageMeta, "createdAt">>(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.threadId, t.id] }),
    index("idx_assistant_messages_thread").on(t.threadId, t.createdAt),
  ]
);

/** Audit of approval-gated tool calls (BE §3.10, §8.10). Kept when threads are purged. */
export const assistantActions = core.table(
  "assistant_actions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    threadId: uuid("thread_id")
      .notNull()
      .references(() => assistantThreads.id, { onDelete: "cascade" }),
    staffId: uuid("staff_id")
      .notNull()
      .references(() => staff.id, { onDelete: "cascade" }),
    toolCallId: text("tool_call_id").notNull(),
    tool: text("tool").notNull(),
    input: jsonb("input").notNull(),
    /** From the tool's `summarize(input)`. */
    summary: text("summary").notNull(),
    status: assistantActionStatus("status").notNull().default("proposed"),
    result: jsonb("result"),
    error: text("error"),
    decidedAt: timestamp("decided_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("assistant_actions_call_uq").on(t.threadId, t.toolCallId),
    index("idx_assistant_actions_staff").on(t.staffId, t.createdAt),
  ]
);

/**
 * Changes the asistente proposes before anything is written (ADR 0007, Calendario BE §3.6).
 * Only `applyProposal` changes data; undo is a server token stored hashed (sha-256).
 */
export const assistantProposals = core.table(
  "assistant_proposals",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** Owner: only they can see, apply or undo it. */
    staffId: uuid("staff_id")
      .notNull()
      .references(() => staff.id, { onDelete: "cascade" }),
    threadId: uuid("thread_id").references(() => assistantThreads.id, { onDelete: "set null" }),
    toolCallId: text("tool_call_id"),
    kind: proposalKind("kind").notNull(),
    status: proposalStatus("status").notNull().default("propuesta"),
    title: text("title").notNull(),
    line: text("line").notNull(),
    rangeFrom: date("range_from"),
    rangeTo: date("range_to"),
    changes: jsonb("changes").$type<ProposalChange[]>().notNull(),
    deferred: jsonb("deferred").$type<DeferredItem[]>().notNull().default(sql`'[]'::jsonb`),
    applied: jsonb("applied").$type<AppliedChange[]>().notNull().default(sql`'[]'::jsonb`),
    undoToken: text("undo_token"),
    undoExpiresAt: timestamp("undo_expires_at", { withTimezone: true }),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    appliedAt: timestamp("applied_at", { withTimezone: true }),
    undoneAt: timestamp("undone_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("assistant_proposals_undo_token_uq").on(t.undoToken),
    index("idx_assistant_proposals_staff").on(t.staffId, t.createdAt.desc()),
    index("idx_assistant_proposals_status").on(t.status, t.expiresAt),
  ]
);
